def is_balanced(root):
    def check(node):
        # Heights in nodes here: empty is 0, so -1 is free to mean unbalanced.
        if node is None:
            return 0
        lh = check(node.left)
        if lh == -1:
            return -1
        rh = check(node.right)
        if rh == -1 or abs(lh - rh) > 1:
            return -1
        return 1 + max(lh, rh)
    return check(root) != -1

