class _Counted(Node):
    reads = 0

    @property
    def left(self):
        _Counted.reads += 1
        return self._l

    @left.setter
    def left(self, v):
        self._l = v

    @property
    def right(self):
        _Counted.reads += 1
        return self._r

    @right.setter
    def right(self, v):
        self._r = v

def _copy(node):
    if node is None:
        return None
    return _Counted(node.val, _copy(node.left), _copy(node.right))

def reads_for(values):
    """How many times is_balanced reads .left or .right on build(values)."""
    t = _copy(build(values))
    _Counted.reads = 0
    is_balanced(t)
    return _Counted.reads

def chain(n):
    """A chain of n nodes, each the left child of the one before."""
    root = node = Node(1)
    for v in range(2, n + 1):
        node.left = Node(v)
        node = node.left
    return root

