def max_root_to_leaf(root):
    if root.left is None and root.right is None:
        return root.val
    best = None
    for child in (root.left, root.right):
        if child is not None:
            s = max_root_to_leaf(child)
            if best is None or s > best:
                best = s
    return root.val + best

